begin;
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
create function pg_temp.reject(q text,label text) returns void language plpgsql as $$begin begin execute q;exception when others then return;end;raise exception 'FAIL accepted: %',label;end $$;
grant execute on function pg_temp.check_true(boolean,text),pg_temp.reject(text,text) to authenticated,service_role,anon;
insert into auth.users(id,email,email_confirmed_at) values('ee190000-0000-4000-8000-000000000001','admin@example.invalid',now()),('ee190000-0000-4000-8000-000000000002','recipient@example.invalid',now());
insert into public.admin_users(user_id,role) values('ee190000-0000-4000-8000-000000000001','owner');
select set_config('request.jwt.claims','{"sub":"ee190000-0000-4000-8000-000000000001","role":"authenticated","amr":[{"method":"password"}]}',true);
select set_config('qa.input',jsonb_build_object('request_id','ee190000-0000-4000-8000-000000000010','key_id','v1','business_name','Merchant & Company','email','recipient@example.invalid','platform_account_id','acct_fixture','livemode',false,'token_sha256',repeat('a',64),'expires_at',clock_timestamp()+interval '1 day')::text,true);
set local role authenticated;
select set_config('qa.invite',public.create_admin_merchant_invitation_v2(current_setting('qa.input')::jsonb)::text,true);
select pg_temp.check_true(public.create_admin_merchant_invitation_v2(current_setting('qa.input')::jsonb||jsonb_build_object('expires_at',clock_timestamp()+interval '2 days'))->>'invitation_id'=current_setting('qa.invite')::jsonb->>'invitation_id','create transport retry returns same invitation');
select pg_temp.check_true(public.create_admin_merchant_invitation_v2(current_setting('qa.input')::jsonb||jsonb_build_object('request_id',upper(current_setting('qa.input')::jsonb->>'request_id')))->>'invitation_id'=current_setting('qa.invite')::jsonb->>'invitation_id','UUID request case normalizes for replay');
select pg_temp.reject('select public.create_admin_merchant_invitation_v2(current_setting(''qa.input'')::jsonb||''{"business_name":"Other"}'')','same request cannot change payload');
select pg_temp.reject('select public.create_admin_merchant_invitation_v2(current_setting(''qa.input'')::jsonb-''request_id'')','creation requires request id');
select pg_temp.check_true(public.get_admin_merchant_invitation_delivery((current_setting('qa.invite')::jsonb->>'invitation_id')::uuid)->>'token_request_id'='ee190000-0000-4000-8000-000000000010','admin can recover token derivation metadata');
select pg_temp.reject('select * from kma_internal.merchant_invitation_requests','browser cannot read private token mapping');
select pg_temp.reject('select * from kma_internal.merchant_invitation_deliveries','browser cannot read private mail attempts');
select pg_temp.reject('select kma_internal.merchant_invitation_delivery_view(null)','private summary function inaccessible');
select pg_temp.reject('select public.finish_merchant_invitation_email(''{}'')','admin cannot forge provider acceptance');
select set_config('qa.fields',jsonb_build_object('template_version',1,'from','KMA <partners@example.invalid>','to','recipient@example.invalid','business_name','Merchant & Company','expires_at',current_setting('qa.invite')::jsonb->>'expires_at','origin','https://partners.example.invalid')::text,true);
select set_config('qa.send',jsonb_build_object('invitation_id',current_setting('qa.invite')::jsonb->>'invitation_id','request_id','ee190000-0000-4000-8000-000000000020','envelope_fields',current_setting('qa.fields')::jsonb,'envelope_sha256',repeat('b',64))::text,true);
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(jsonb_set(current_setting(''qa.send'')::jsonb,''{envelope_fields,to}'',''"attacker@example.invalid"''))','recipient cannot be substituted');
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(jsonb_set(current_setting(''qa.send'')::jsonb,''{envelope_fields}'',(current_setting(''qa.fields'')::jsonb-''template_version'')||''{"other":1}''))','missing template version rejected');
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(jsonb_set(current_setting(''qa.send'')::jsonb,''{envelope_fields,template_version}'',''"1"''))','template version must be numeric');
select set_config('qa.pending',public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb)::text,true);
select pg_temp.check_true((current_setting('qa.pending')::jsonb->>'send')::boolean,'first request leases one send');
select pg_temp.check_true(not(public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb)->>'send')::boolean,'duplicate pending request does not send twice');
select pg_temp.check_true(not(public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb||jsonb_build_object('request_id',gen_random_uuid()))->>'send')::boolean,'different request during lease does not send twice');
select pg_temp.reject('select public.create_admin_merchant_invitation_v2(current_setting(''qa.input'')::jsonb||jsonb_build_object(''request_id'',gen_random_uuid(),''merchant_id'',current_setting(''qa.invite'')::jsonb->>''merchant_id'',''token_sha256'',repeat(''d'',64)))','renewal cooldown cannot invalidate the current invitation');
reset role;set local role service_role;
select pg_temp.reject('select public.finish_merchant_invitation_email(current_setting(''qa.pending'')::jsonb||jsonb_build_object(''lease_id'',gen_random_uuid(),''status'',''sent'',''provider_id'',''email_123''))','wrong lease cannot finish');
select public.finish_merchant_invitation_email(current_setting('qa.pending')::jsonb||'{"status":"unknown","error_code":"provider_response_unknown"}');
reset role;
update kma_internal.merchant_invitation_deliveries set retry_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.pending')::jsonb->>'delivery_id')::uuid;
set local role authenticated;
select set_config('qa.replayed',public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb||jsonb_build_object('request_id',gen_random_uuid()))::text,true);
select pg_temp.check_true(current_setting('qa.replayed')::jsonb->>'idempotency_key'=current_setting('qa.pending')::jsonb->>'idempotency_key','uncertain resend retains provider operation key');
select pg_temp.check_true(current_setting('qa.replayed')::jsonb->>'lease_id'<>current_setting('qa.pending')::jsonb->>'lease_id','uncertain retry gets a fresh lease');
reset role;set local role service_role;
select public.finish_merchant_invitation_email(current_setting('qa.replayed')::jsonb||'{"status":"sent","provider_id":"email_123"}');
reset role;set local role authenticated;
select pg_temp.check_true(not(public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb)->>'send')::boolean,'accepted send replay does not create another email');
select pg_temp.check_true(public.get_admin_merchant_invitation_delivery((current_setting('qa.invite')::jsonb->>'invitation_id')::uuid)->'delivery'->>'status'='sent','accepted outcome survives reload');
select pg_temp.check_true(public.get_admin_merchant_connections()->'merchants'->0->'connections'->0->'latest_invitation'->'delivery'->>'status'='sent','workspace includes delivery summary');
reset role;
select pg_temp.check_true((select count(*)=1 from public.merchant_businesses),'transport replay did not duplicate merchant');
select pg_temp.check_true((select count(*)=1 from kma_internal.merchant_invitation_deliveries),'pending/unknown retries retain single durable operation');
update kma_internal.merchant_invitation_deliveries set retry_at=clock_timestamp()-interval '1 second';
set local role authenticated;
select set_config('qa.resend',public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb||jsonb_build_object('request_id',gen_random_uuid()))::text,true);
select pg_temp.check_true((current_setting('qa.resend')::jsonb->>'send')::boolean and current_setting('qa.resend')::jsonb->>'idempotency_key'<>current_setting('qa.pending')::jsonb->>'idempotency_key','explicit resend after acceptance has distinct mail operation');
reset role;set local role service_role;
select public.finish_merchant_invitation_email(current_setting('qa.resend')::jsonb||'{"status":"unknown","error_code":"provider_response_unknown"}');
reset role;
update kma_internal.merchant_invitation_deliveries set retry_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.resend')::jsonb->>'delivery_id')::uuid;
set local role authenticated;
select set_config('qa.frozen',public.prepare_admin_merchant_invitation_email(jsonb_set(current_setting('qa.send')::jsonb||jsonb_build_object('request_id',gen_random_uuid()),'{envelope_fields,from}','"New <changed@example.invalid>"'))::text,true);
select pg_temp.check_true((current_setting('qa.frozen')::jsonb->>'needs_frozen_envelope')::boolean and current_setting('qa.frozen')::jsonb->'envelope_fields'->>'from'='KMA <partners@example.invalid>','changed sender retrieves original frozen envelope without sending');
reset role;
update kma_internal.merchant_invitation_deliveries set first_attempt_at=clock_timestamp()-interval '23 hours',retry_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.resend')::jsonb->>'delivery_id')::uuid;
-- Keep old operation latest for this isolated boundary scenario.
update kma_internal.merchant_invitation_deliveries set first_attempt_at=clock_timestamp()-interval '24 hours' where id=(current_setting('qa.pending')::jsonb->>'delivery_id')::uuid;
set local role authenticated;
select pg_temp.check_true(not(public.prepare_admin_merchant_invitation_email(current_setting('qa.send')::jsonb||jsonb_build_object('request_id',gen_random_uuid()))->>'send')::boolean,'23 hour uncertain delivery cannot send outside safe idempotency window');
select pg_temp.check_true(not(public.get_admin_merchant_invitation_delivery((current_setting('qa.invite')::jsonb->>'invitation_id')::uuid)->'delivery'->>'can_retry')::boolean,'expired idempotency window disables resend');
select set_config('qa.renew',public.create_admin_merchant_invitation_v2(current_setting('qa.input')::jsonb||jsonb_build_object('request_id',gen_random_uuid(),'merchant_id',current_setting('qa.invite')::jsonb->>'merchant_id','token_sha256',repeat('c',64)))::text,true);
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(current_setting(''qa.send'')::jsonb)','renewal invalidates old invitation sends');
select pg_temp.check_true(public.get_admin_merchant_invitation_delivery((current_setting('qa.invite')::jsonb->>'invitation_id')::uuid)->>'status'='revoked','renewal explicitly revokes old invite');
-- New invitation provides a fresh operation for lease/conflict and expiry checks.
select set_config('qa.newsend',(current_setting('qa.send')::jsonb||jsonb_build_object('invitation_id',current_setting('qa.renew')::jsonb->>'invitation_id','request_id',gen_random_uuid()))::text,true);
select set_config('qa.newpending',public.prepare_admin_merchant_invitation_email(current_setting('qa.newsend')::jsonb)::text,true);
reset role;
update kma_internal.merchant_invitation_deliveries set leased_until=clock_timestamp()-interval '1 second',retry_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.newpending')::jsonb->>'delivery_id')::uuid;
set local role authenticated;
select pg_temp.check_true(public.get_admin_merchant_invitation_delivery((current_setting('qa.renew')::jsonb->>'invitation_id')::uuid)->'delivery'->>'status'='unknown','expired in-flight lease reports uncertainty');
select set_config('qa.recovered',public.prepare_admin_merchant_invitation_email(current_setting('qa.newsend')::jsonb)::text,true);
select pg_temp.check_true((current_setting('qa.recovered')::jsonb->>'send')::boolean and current_setting('qa.recovered')::jsonb->>'idempotency_key'=current_setting('qa.newpending')::jsonb->>'idempotency_key','expired lease safely resumes identical provider operation');
reset role;set local role service_role;
select public.finish_merchant_invitation_email(current_setting('qa.recovered')::jsonb||'{"status":"unknown","error_code":"provider_payload_conflict"}');
reset role;
update kma_internal.merchant_invitation_deliveries set retry_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.newpending')::jsonb->>'delivery_id')::uuid;
set local role authenticated;
select pg_temp.check_true(not(public.get_admin_merchant_invitation_delivery((current_setting('qa.renew')::jsonb->>'invitation_id')::uuid)->'delivery'->>'can_retry')::boolean,'provider payload conflict is terminal');
select pg_temp.check_true(not(public.prepare_admin_merchant_invitation_email(current_setting('qa.newsend')::jsonb||jsonb_build_object('request_id',gen_random_uuid()))->>'send')::boolean,'payload conflict cannot mint a new provider key');
reset role;
update public.merchant_invitations set expires_at=clock_timestamp()-interval '1 second' where id=(current_setting('qa.renew')::jsonb->>'invitation_id')::uuid;
set local role authenticated;
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(current_setting(''qa.newsend'')::jsonb)','expired invitation cannot send');
select set_config('qa.legacy',public.create_admin_merchant_invitation(current_setting('qa.input')::jsonb||jsonb_build_object('email','legacy@example.invalid','token_sha256',repeat('e',64)))::text,true);
select pg_temp.check_true(not(public.get_admin_merchant_invitation_delivery((current_setting('qa.legacy')::jsonb->>'invitation_id')::uuid)->'delivery'->>'can_retry')::boolean,'legacy hash-only invite requires renewal rather than broken resend');
reset role;
-- Synthetic immutable attempt rows exercise the real recipient and actor rate guards.
insert into kma_internal.merchant_invitation_deliveries(id,invitation_id,actor_id,status,envelope_fields,envelope_sha256,lease_id,leased_until,first_attempt_at,retry_at)
select gen_random_uuid(),(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid,'ee190000-0000-4000-8000-000000000001','sent',current_setting('qa.fields')::jsonb,repeat('f',64),gen_random_uuid(),clock_timestamp()-interval '1 second',clock_timestamp()-interval '1 minute',clock_timestamp()-interval '1 second' from generate_series(1,5);
set local role authenticated;
select set_config('qa.limited',public.create_admin_merchant_invitation_v2(current_setting('qa.input')::jsonb||jsonb_build_object('request_id',gen_random_uuid(),'merchant_id',current_setting('qa.invite')::jsonb->>'merchant_id','token_sha256',repeat('7',64)))::text,true);
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(current_setting(''qa.send'')::jsonb||jsonb_build_object(''request_id'',gen_random_uuid(),''invitation_id'',current_setting(''qa.limited'')::jsonb->>''invitation_id''))','recipient hourly limit enforced across invitations');
select set_config('qa.other',public.create_admin_merchant_invitation_v2(current_setting('qa.input')::jsonb||jsonb_build_object('request_id',gen_random_uuid(),'email','other@example.invalid','token_sha256',repeat('8',64)))::text,true);
reset role;
insert into kma_internal.merchant_invitation_deliveries(id,invitation_id,actor_id,status,envelope_fields,envelope_sha256,lease_id,leased_until,first_attempt_at,retry_at)
select gen_random_uuid(),(current_setting('qa.invite')::jsonb->>'invitation_id')::uuid,'ee190000-0000-4000-8000-000000000001','sent',current_setting('qa.fields')::jsonb,repeat('f',64),gen_random_uuid(),clock_timestamp()-interval '1 second',clock_timestamp()-interval '1 minute',clock_timestamp()-interval '1 second' from generate_series(1,20);
set local role authenticated;
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(jsonb_set(current_setting(''qa.send'')::jsonb||jsonb_build_object(''request_id'',gen_random_uuid(),''invitation_id'',current_setting(''qa.other'')::jsonb->>''invitation_id''),''{envelope_fields,to}'',''"other@example.invalid"''))','admin hourly limit enforced across recipients');
select set_config('request.jwt.claims','{"sub":"ee190000-0000-4000-8000-000000000002","role":"authenticated","amr":[{"method":"password"}]}',true);
select pg_temp.reject('select public.get_admin_merchant_invitation_delivery((current_setting(''qa.renew'')::jsonb->>''invitation_id'')::uuid)','recipient cannot obtain admin invitation metadata');
select pg_temp.reject('select public.prepare_admin_merchant_invitation_email(current_setting(''qa.send'')::jsonb)','recipient cannot send invitations');
select pg_temp.reject('select public.create_admin_merchant_invitation_v2(current_setting(''qa.input'')::jsonb)','recipient cannot replay admin creation request');
reset role;set local role anon;
select pg_temp.reject('select public.get_admin_merchant_invitation_delivery(null)','anonymous cannot fetch invitation');
select pg_temp.reject('select public.finish_merchant_invitation_email(''{}'')','anonymous cannot forge mail receipt');
reset role;
select pg_temp.check_true(not has_function_privilege('authenticated','public.finish_merchant_invitation_email(jsonb)','EXECUTE') and has_function_privilege('service_role','public.finish_merchant_invitation_email(jsonb)','EXECUTE'),'provider receipt is service-only');
select pg_temp.check_true(not has_function_privilege('service_role','public.get_admin_merchant_invitation_delivery(uuid)','EXECUTE'),'service cannot bypass authenticated admin read');
rollback;
